package app.dayflow;
import android.content.Context;
import android.widget.*;
import org.json.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.regex.*;
final class NoteTasks {
 static void entry(MainActivity a,LinearLayout page,JSONObject note){if(note.optString("kind").equals("note"))page.addView(Ui.button(a,"提取 Markdown 勾选项为待办",false,()->{try{String[] lines=note.optString("content").split("\n",-1);int count=0;for(int i=0;i<lines.length&&count<100;i++){Matcher m=Pattern.compile("^\\s*[-*+] \\[([ xX])\\] (.+)$").matcher(lines[i]);if(!m.matches())continue;String title=m.group(2),id=UUID.nameUUIDFromBytes(("md-task:"+note.optString("id")+":"+i+":"+title).getBytes(StandardCharsets.UTF_8)).toString();if(Data.get(a).find(id)!=null)continue;JSONObject r=Data.make("task",title).put("id",id).put("source_note_id",note.getString("id")).put("source_note_line",i).put("source_note_text",title).put("content","来自笔记「"+note.optString("title")+"」");if(!m.group(1).equals(" "))r.put("completed",java.time.Instant.now().toString()).put("status","done");Data.validate(r);Data.get(a).save(r);count++;}a.changed();a.message("已提取 "+count+" 项，已有内容未覆盖");}catch(Exception e){a.message(e.getMessage());}}));else if(!note.optString("source_note_id").isEmpty())page.addView(Ui.button(a,"查看来源笔记",false,()->{try{JSONObject original=Data.get(a).find(note.optString("source_note_id"));if(original==null||original.optBoolean("deleted"))throw new Exception("来源笔记已删除");a.detail(original);}catch(Exception e){a.message(e.getMessage());}}));}
 static void fromNote(Context c,JSONObject note)throws Exception{String[] lines=note.optString("content").split("\n",-1);int seen=0;for(int i=0;i<lines.length&&seen<100;i++){Matcher m=Pattern.compile("^\\s*[-*+] \\[([ xX])\\] (.+)$").matcher(lines[i]);if(!m.matches())continue;seen++;String id=UUID.nameUUIDFromBytes(("md-task:"+note.optString("id")+":"+i+":"+m.group(2)).getBytes(StandardCharsets.UTF_8)).toString();JSONObject task=Data.get(c).find(id);if(task==null||task.optBoolean("deleted")||!note.optString("id").equals(task.optString("source_note_id")))continue;boolean checked=!m.group(1).equals(" ");if(checked!=!task.optString("completed").isEmpty())TaskActions.complete(c,task);}}
 static void updateSource(Context c,JSONObject task)throws Exception{String id=task.optString("source_note_id");if(id.isEmpty())return;JSONObject note=Data.get(c).find(id);if(note==null||note.optBoolean("deleted"))return;String[] lines=note.optString("content").split("\n",-1);int line=task.optInt("source_note_line",-1);if(line<0||line>=lines.length)return;Matcher m=Pattern.compile("^(\\s*[-*+] \\[)[ xX](\\] )(.+)$").matcher(lines[line]);if(!m.matches()||!m.group(3).equals(task.optString("source_note_text")))return;lines[line]=m.group(1)+(task.optString("completed").isEmpty()?" ":"x")+m.group(2)+m.group(3);String changed=String.join("\n",lines);if(changed.equals(note.optString("content")))return;String expected=note.optString("revision");note.put("content",changed);Data.get(c).bridgeSave(note,expected);}
}
